import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract(data):
    pkgs = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                pkgs[(name, pkg['id'])] = pkg['resolvedVersion']
    return pkgs

b, a = extract(baseline), extract(after)
if b == a:
    print('MATCH: All packages resolve to identical versions.')
else:
    for k in b:
        if k not in a: print(f'REMOVED: {k}')
        elif b[k] != a[k]: print(f'CHANGED: {k} {b[k]} -> {a[k]}')
    for k in a:
        if k not in b: print(f'ADDED: {k}')
"

